// File: prototype/assets/app.css (css)
/* ===========================================================
   SmashBook — Sistem Pengelolaan Lapangan Badminton
   Stylesheet prototipe (tanpa dependensi eksternal)
   =========================================================== */

:root {
  --bg: #f1f5f9;
  --panel: #ffffff;
  --ink: #0f172a;
  --ink-soft: #334155;
  --muted: #64748b;
  --line: #e2e8f0;
  --line-soft: #f1f5f9;

  --brand: #10b981;
  --brand-dark: #059669;
  --brand-soft: #ecfdf5;
  --nav: #0b1220;
  --nav-2: #131c2e;
  --nav-ink: #94a3b8;

  --blue: #3b82f6;
  --amber: #f59e0b;
  --red: #ef4444;
  --violet: #8b5cf6;
  --cyan: #06b6d4;

  --r: 14px;
  --r-sm: 9px;
  --shadow: 0 1px 2px rgba(15, 23, 42, .06), 0 10px 28px -14px rgba(15, 23, 42, .22);
  --shadow-lg: 0 24px 60px -18px rgba(15, 23, 42, .35);
  font-synthesis: none;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: "Segoe UI", Inter, system-ui, -apple-system, Roboto, Arial, sans-serif;
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
h1, h2, h3, h4 { margin: 0; font-weight: 650; letter-spacing: -.01em; }
p { margin: 0; }
button { font-family: inherit; }

/* ---------------- Layout ---------------- */

.app {
  display: grid;
  grid-template-columns: 244px minmax(0, 1fr);
  min-height: 100vh;
}

.sidebar {
  background: var(--nav);
  color: var(--nav-ink);
  display: flex;
  flex-direction: column;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 18px 18px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, .07);
}
.brand .logo {
  width: 38px; height: 38px;
  border-radius: 11px;
  display: grid; place-items: center;
  background: linear-gradient(140deg, var(--brand), #34d399);
  color: #04231a; font-weight: 800; font-size: 17px;
  box-shadow: 0 6px 16px -6px rgba(16, 185, 129, .8);
  flex: none;
}
.brand .name { color: #fff; font-weight: 700; font-size: 15px; letter-spacing: -.01em; }
.brand .sub { font-size: 11px; color: var(--nav-ink); }

.nav { padding: 12px 10px 22px; }
.nav-title {
  font-size: 10.5px; text-transform: uppercase; letter-spacing: .09em;
  color: #5b6b85; padding: 14px 10px 6px; font-weight: 700;
}
.nav a {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 10px; border-radius: 9px;
  font-size: 13.5px; color: var(--nav-ink);
  transition: background .15s, color .15s;
}
.nav a:hover { background: var(--nav-2); color: #e2e8f0; }
.nav a.active {
  background: linear-gradient(90deg, rgba(16, 185, 129, .18), rgba(16, 185, 129, .04));
  color: #fff; font-weight: 600;
  box-shadow: inset 2px 0 0 var(--brand);
}
.nav a svg { width: 17px; height: 17px; flex: none; opacity: .9; }
.nav a .tag {
  margin-left: auto; font-size: 10px; font-weight: 700;
  background: var(--red); color: #fff; border-radius: 20px; padding: 1px 7px;
}

.sidebar-foot {
  margin-top: auto; padding: 14px 16px 18px;
  border-top: 1px solid rgba(255, 255, 255, .07);
  font-size: 11.5px; color: #64748b;
}

.main { min-width: 0; display: flex; flex-direction: column; }

.topbar {
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  padding: 12px 22px;
  display: flex; align-items: center; gap: 14px; row-gap: 8px;
  flex-wrap: wrap;
  position: sticky; top: 0; z-index: 20;
}
.topbar .shift-pill { flex: 0 1 auto; min-width: 0; overflow: hidden; }
.topbar h1 { font-size: 17px; }
.topbar .crumb { font-size: 12px; color: var(--muted); }
.topbar .spacer { flex: 1; }

.shift-pill {
  display: flex; align-items: center; gap: 8px;
  background: var(--brand-soft); border: 1px solid #a7f3d0;
  color: #065f46; border-radius: 30px; padding: 6px 13px;
  font-size: 12px; font-weight: 600; white-space: nowrap;
}
.dot { width: 7px; height: 7px; border-radius: 50%; background: var(--brand); flex: none; }
.dot.red { background: var(--red); }
.dot.amber { background: var(--amber); }
.dot.blue { background: var(--blue); }
.dot.grey { background: #94a3b8; }

.user {
  display: flex; align-items: center; gap: 9px;
  padding-left: 16px; border-left: 1px solid var(--line);
}
.avatar {
  width: 34px; height: 34px; border-radius: 50%;
  background: linear-gradient(140deg, #0f172a, #334155);
  color: #fff; display: grid; place-items: center;
  font-weight: 700; font-size: 13px; flex: none;
}
.user .nm { font-weight: 600; font-size: 13px; line-height: 1.2; }
.user .rl { font-size: 11px; color: var(--muted); }

.content { padding: 22px; display: flex; flex-direction: column; gap: 18px; flex: 1; }

/* ---------------- Card & grid ---------------- */

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--r);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.card-h {
  display: flex; align-items: center; gap: 12px;
  padding: 14px 16px; border-bottom: 1px solid var(--line);
}
.card-h h3 { font-size: 14.5px; }
.card-h .sub { font-size: 12px; color: var(--muted); }
.card-h .right { margin-left: auto; display: flex; align-items: center; gap: 8px; }
.card-b { padding: 16px; }
.card-b.tight { padding: 0; }

.grid { display: grid; gap: 16px; }
.g2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.g3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.g4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.g-2-1 { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }
.g-1-2 { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); }
.g-3-2 { grid-template-columns: minmax(0, 3fr) minmax(0, 2fr); }
.row { display: flex; gap: 10px; align-items: center; }
.row.wrap { flex-wrap: wrap; }
.row.between { justify-content: space-between; }
.stack { display: flex; flex-direction: column; gap: 10px; }

/* ---------------- KPI ---------------- */

.kpi { padding: 15px 16px; display: flex; flex-direction: column; gap: 7px; }
.kpi .lbl { font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 6px; }
.kpi .val { font-size: 23px; font-weight: 750; letter-spacing: -.02em; }
.kpi .dlt { font-size: 11.5px; font-weight: 600; }
.kpi .dlt.up { color: #059669; }
.kpi .dlt.down { color: var(--red); }
.kpi .dlt.neutral { color: var(--muted); }
.kpi .ico {
  width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center;
  font-size: 15px;
}
.ico.brand { background: var(--brand-soft); color: #047857; }
.ico.blue { background: #eff6ff; color: #1d4ed8; }
.ico.amber { background: #fffbeb; color: #b45309; }
.ico.violet { background: #f5f3ff; color: #6d28d9; }
.ico.red { background: #fef2f2; color: #b91c1c; }
.ico.cyan { background: #ecfeff; color: #0e7490; }

/* ---------------- Buttons ---------------- */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  border: 1px solid var(--line);
  background: #fff; color: var(--ink);
  padding: 9px 14px; border-radius: 10px;
  font-size: 13px; font-weight: 600; cursor: pointer;
  transition: background .15s, border-color .15s, transform .05s;
  white-space: nowrap;
}
.btn:hover { background: #f8fafc; border-color: #cbd5e1; }
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--brand); border-color: var(--brand); color: #04231a; }
.btn-primary:hover { background: var(--brand-dark); border-color: var(--brand-dark); color: #fff; }
.btn-dark { background: #0f172a; border-color: #0f172a; color: #fff; }
.btn-dark:hover { background: #1e293b; }
.btn-danger { background: #fff; border-color: #fecaca; color: #b91c1c; }
.btn-danger:hover { background: #fef2f2; }
.btn-ghost { background: transparent; border-color: transparent; color: var(--muted); }
.btn-ghost:hover { background: var(--line-soft); color: var(--ink); }
.btn-sm { padding: 6px 10px; font-size: 12px; border-radius: 8px; }
.btn-lg { padding: 13px 18px; font-size: 14.5px; border-radius: 12px; }
.btn-block { width: 100%; }
.btn[disabled] { opacity: .5; cursor: not-allowed; }
.btn svg { width: 15px; height: 15px; }

.btn-group { display: inline-flex; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: #fff; }
.btn-group button {
  border: 0; background: transparent; padding: 8px 13px; font-size: 12.5px;
  font-weight: 600; color: var(--muted); cursor: pointer;
}
.btn-group button + button { border-left: 1px solid var(--line); }
.btn-group button.on { background: #0f172a; color: #fff; }

/* ---------------- Form ---------------- */

.field { display: flex; flex-direction: column; gap: 5px; }
.field > label { font-size: 12px; font-weight: 600; color: var(--ink-soft); }
.field .hint { font-size: 11.5px; color: var(--muted); }

.input, .select, textarea.input {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
  font-size: 13.5px;
  color: var(--ink);
  font-family: inherit;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
}
.input:focus, .select:focus, textarea.input:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(16, 185, 129, .13);
}
.select {
  appearance: none;
  background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='14' height='14' viewBox='0 0 24 24' fill='none' stroke='%2364748b' stroke-width='2.5'%3E%3Cpath d='M6 9l6 6 6-6'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 10px center;
  padding-right: 32px;
}
.search { position: relative; }
.search .input { padding-left: 34px; }
.search svg {
  position: absolute; left: 10px; top: 50%; transform: translateY(-50%);
  width: 16px; height: 16px; color: var(--muted);
}
.form-grid { display: grid; gap: 13px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
.form-grid .full { grid-column: 1 / -1; }

/* ---------------- Badge & chip ---------------- */

.badge {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 3px 9px; border-radius: 20px;
  font-size: 11.5px; font-weight: 650; white-space: nowrap;
}
.badge.green { background: var(--brand-soft); color: #047857; }
.badge.blue { background: #eff6ff; color: #1d4ed8; }
.badge.amber { background: #fffbeb; color: #b45309; }
.badge.red { background: #fef2f2; color: #b91c1c; }
.badge.violet { background: #f5f3ff; color: #6d28d9; }
.badge.grey { background: #f1f5f9; color: #475569; }
.badge.dark { background: #0f172a; color: #fff; }

.chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 11px; border-radius: 20px; border: 1px solid var(--line);
  background: #fff; font-size: 12px; font-weight: 600; color: var(--ink-soft);
  cursor: pointer;
}
.chip.on { background: #0f172a; border-color: #0f172a; color: #fff; }

/* ---------------- Table ---------------- */

.table-wrap { overflow-x: auto; }
table.tbl { width: 100%; border-collapse: collapse; font-size: 13px; }
table.tbl thead th {
  text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: .06em;
  color: var(--muted); font-weight: 700; background: #f8fafc;
  padding: 10px 14px; border-bottom: 1px solid var(--line); white-space: nowrap;
}
table.tbl tbody td { padding: 11px 14px; border-bottom: 1px solid var(--line-soft); vertical-align: middle; }
table.tbl tbody tr:hover { background: #fafcfe; }
table.tbl tbody tr:last-child td { border-bottom: 0; }
table.tbl .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
table.tbl .strong { font-weight: 650; }
table.tbl .muted { color: var(--muted); font-size: 12px; }
.tbl-actions { display: flex; gap: 5px; justify-content: flex-end; }

.tfoot {
  display: flex; justify-content: flex-end; align-items: center; gap: 22px;
  padding: 13px 16px; border-top: 1px solid var(--line); background: #f8fafc;
  font-size: 13px;
}
.tfoot .lbl { color: var(--muted); font-size: 12px; }
.tfoot .grand { font-size: 19px; font-weight: 750; color: #047857; }

/* ---------------- Progress / bars ---------------- */

.bar { height: 7px; border-radius: 20px; background: var(--line); overflow: hidden; }
.bar > span { display: block; height: 100%; border-radius: 20px; background: var(--brand); }
.bar > span.amber { background: var(--amber); }
.bar > span.red { background: var(--red); }
.bar > span.blue { background: var(--blue); }

.chart { display: flex; align-items: flex-end; gap: 10px; height: 178px; padding: 6px 2px 0; }
.chart .col { flex: 1; display: flex; flex-direction: column; justify-content: flex-end; gap: 5px; height: 100%; }
.chart .bars { flex: 1; display: flex; gap: 3px; align-items: flex-end; }
.chart .bars i { flex: 1; border-radius: 5px 5px 0 0; display: block; background: var(--brand); min-height: 3px; }
.chart .bars i.pos { background: var(--blue); }
.chart .bars i.exp { background: #fca5a5; }
.chart .cap { text-align: center; font-size: 11px; color: var(--muted); font-weight: 600; }
.legend { display: flex; gap: 14px; font-size: 12px; color: var(--muted); }
.legend i { width: 9px; height: 9px; border-radius: 3px; display: inline-block; margin-right: 5px; }

/* ---------------- Schedule board ---------------- */

.board { display: grid; grid-template-columns: 74px repeat(4, minmax(120px, 1fr)); min-width: 640px; }
.board .hd {
  font-size: 11.5px; font-weight: 700; color: var(--muted); text-transform: uppercase;
  letter-spacing: .05em; padding: 9px 10px; background: #f8fafc;
  border-bottom: 1px solid var(--line); text-align: center;
}
.board .hd:first-child { text-align: left; }
.board .tm {
  font-size: 12px; color: var(--muted); font-weight: 600; padding: 0 10px;
  border-right: 1px solid var(--line); border-bottom: 1px solid var(--line-soft);
  display: flex; align-items: center; height: 46px;
}
.slot {
  height: 46px; border-bottom: 1px solid var(--line-soft); border-right: 1px solid var(--line-soft);
  padding: 4px 5px;
}
.slot .cell {
  height: 100%; border-radius: 8px; display: flex; flex-direction: column; justify-content: center;
  padding: 0 9px; cursor: pointer; border: 1px dashed transparent;
  background: #f8fafc; transition: background .15s;
}
.slot .cell:hover { background: var(--brand-soft); border-color: #a7f3d0; }
.slot .cell small { font-size: 11px; color: var(--muted); }
.slot .cell b { font-size: 12px; font-weight: 650; }
.slot .cell.bk {
  background: #eff6ff; border: 1px solid #bfdbfe; cursor: default;
}
.slot .cell.bk b { color: #1e40af; }
.slot .cell.mb { background: #ecfdf5; border: 1px solid #a7f3d0; cursor: default; }
.slot .cell.mb b { color: #047857; }
.slot .cell.hd { background: #fffbeb; border: 1px solid #fde68a; cursor: default; }
.slot .cell.peak { background: #fef2f2; border: 1px solid #fecaca; cursor: default; }
.slot .cell.peak b { color: #b91c1c; }
.peak-row .tm { background: #fffbeb; color: #b45309; }

/* ---------------- POS ---------------- */

.pos-grid { display: grid; grid-template-columns: minmax(0, 1fr) 396px; gap: 16px; align-items: start; }
.prod-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 11px; }
.prod {
  border: 1px solid var(--line); border-radius: 12px; padding: 11px; background: #fff;
  cursor: pointer; display: flex; flex-direction: column; gap: 6px; transition: box-shadow .15s, border-color .15s;
}
.prod:hover { border-color: var(--brand); box-shadow: 0 6px 18px -10px rgba(16, 185, 129, .7); }
.prod .thumb {
  height: 54px; border-radius: 9px; display: grid; place-items: center; font-size: 22px;
  background: #f1f5f9;
}
.prod .nm { font-size: 12.8px; font-weight: 620; line-height: 1.3; }
.prod .pr { font-size: 13.5px; font-weight: 750; color: #047857; }
.prod .st { font-size: 11px; color: var(--muted); display: flex; justify-content: space-between; }
.prod.out { opacity: .55; }
.prod.out .pr { color: var(--red); }

.cart { position: sticky; top: 82px; }
.cart-items { max-height: 300px; overflow-y: auto; }
.cart-item {
  display: grid; grid-template-columns: 1fr auto; gap: 4px 10px;
  padding: 11px 16px; border-bottom: 1px solid var(--line-soft);
}
.cart-item .nm { font-size: 13px; font-weight: 620; }
.cart-item .meta { font-size: 11.5px; color: var(--muted); }
.cart-item .amt { text-align: right; font-weight: 700; font-size: 13px; }
.qty { display: inline-flex; align-items: center; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.qty button { border: 0; background: #f8fafc; width: 25px; height: 25px; cursor: pointer; font-weight: 700; color: var(--ink-soft); }
.qty button:hover { background: var(--line); }
.qty span { min-width: 30px; text-align: center; font-size: 12.5px; font-weight: 650; }
.sum { display: flex; justify-content: space-between; font-size: 13px; padding: 4px 0; }
.sum.big { font-size: 16px; font-weight: 750; padding-top: 9px; border-top: 1px dashed var(--line); }
.sum .lbl { color: var(--muted); }
.pay-methods { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.pay {
  border: 1px solid var(--line); border-radius: 10px; padding: 9px 6px; text-align: center;
  font-size: 12px; font-weight: 650; cursor: pointer; background: #fff; color: var(--ink-soft);
}
.pay.on { background: #0f172a; border-color: #0f172a; color: #fff; }
.pay small { display: block; font-size: 10.5px; font-weight: 500; opacity: .75; }
.quick-cash { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.quick-cash button {
  border: 1px solid var(--line); background: #fff; border-radius: 8px; padding: 7px 4px;
  font-size: 12px; font-weight: 650; cursor: pointer; color: var(--ink-soft);
}
.quick-cash button:hover { border-color: var(--brand); color: #047857; }

/* ---------------- Kas ---------------- */

.money-row {
  display: flex; align-items: center; gap: 12px; padding: 13px 0;
  border-bottom: 1px solid var(--line-soft);
}
.money-row:last-child { border-bottom: 0; }
.money-row .ic {
  width: 34px; height: 34px; border-radius: 9px; display: grid; place-items: center; font-size: 15px; flex: none;
}
.money-row .t { flex: 1; }
.money-row .t b { font-size: 13.3px; font-weight: 620; display: block; }
.money-row .t small { font-size: 11.5px; color: var(--muted); }
.money-row .v { font-weight: 700; font-variant-numeric: tabular-nums; }
.v.in { color: #047857; }
.v.out { color: var(--red); }

.recon { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); border-radius: 12px; overflow: hidden; }
.recon > div { background: #fff; padding: 15px 16px; }
.recon .l { font-size: 11.5px; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; font-weight: 700; }
.recon .v { font-size: 21px; font-weight: 750; margin-top: 3px; font-variant-numeric: tabular-nums; }

.money-input { position: relative; }
.money-input .rp {
  position: absolute; left: 11px; top: 50%; transform: translateY(-50%);
  font-size: 13px; color: var(--muted); font-weight: 600;
}
.money-input .input { padding-left: 34px; font-size: 16px; font-weight: 700; }

/* ---------------- Tabs & modal ---------------- */

.tabs { display: flex; gap: 3px; border-bottom: 1px solid var(--line); padding: 0 16px; background: #fff; }
.tabs button {
  border: 0; background: transparent; padding: 12px 13px; font-size: 13px; font-weight: 620;
  color: var(--muted); cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px;
}
.tabs button.on { color: var(--ink); border-bottom-color: var(--brand); }

.modal-mask {
  position: fixed; inset: 0; background: rgba(15, 23, 42, .5);
  display: none; align-items: flex-start; justify-content: center;
  padding: 40px 18px; z-index: 60; overflow-y: auto;
  backdrop-filter: blur(2px);
}
.modal-mask.open { display: flex; }
.modal {
  background: #fff; border-radius: 16px; width: 100%; max-width: 620px;
  box-shadow: var(--shadow-lg); overflow: hidden;
}
.modal.wide { max-width: 900px; }
.modal-h { display: flex; align-items: center; gap: 12px; padding: 16px 18px; border-bottom: 1px solid var(--line); }
.modal-h h3 { font-size: 15.5px; }
.modal-h .sub { font-size: 12px; color: var(--muted); }
.modal-h .x {
  margin-left: auto; border: 0; background: #f1f5f9; width: 30px; height: 30px;
  border-radius: 8px; cursor: pointer; font-size: 15px; color: var(--ink-soft); line-height: 1;
}
.modal-b { padding: 18px; max-height: 66vh; overflow-y: auto; }
.modal-f {
  display: flex; gap: 10px; justify-content: flex-end;
  padding: 14px 18px; border-top: 1px solid var(--line); background: #f8fafc;
}

/* ---------------- Misc ---------------- */

